#include "tactical_living_internal.hpp"
#include "view/render_check.h"
#include <algorithm>
#include <cmath>
#include <numbers>
namespace transartica::panels {
using namespace visual;namespace {constexpr double pi=std::numbers::pi,tau=2*pi,cell=.5;constexpr std::array<double,16>bayer{{0,.5,.125,.625,.75,.25,.875,.375,.1875,.6875,.0625,.5625,.9375,.4375,.8125,.3125}};constexpr unsigned palette[]={0x272d35,0x663627,0xcc4c20,0xf58a27,0xffd66b,0xfff4cd};}
void LivingEffects::Impl::add_volume(std::string kind,Point point,Point direction,double scale){++volume_serial;volume_random.seed(art::visual_seed(kind,point,volume_serial));const bool blast=kind=="destroy"||kind=="dynamite"||kind=="explosion"||kind=="rocket-impact",gun=kind=="cannon"||kind=="muzzle";if(!blast&&!gun&&kind!="impact")return;if(fields.size()>=4){auto found=std::find_if(fields.begin(),fields.end(),[](const Blast&b){return!b.blast;});fields.erase(found==fields.end()?fields.begin():found);}Blast field;field.kind=std::move(kind);field.point=point;field.direction=direction;field.scale=scale;field.blast=blast;field.gun=gun;field.life=blast?180:65;field.width=blast?96:64;field.height=blast?128:64;field.anchor={field.width/2.,gun?field.height/2.:field.height-18.};field.bytes.resize(field.width*field.height*4);const int amount=blast?64:field.kind=="cannon"?32:16;for(int i=0;i<amount;++i)field.motes.push_back(mote(field,i));fields.push_back(std::move(field));}
Mote LivingEffects::Impl::mote(const Blast&field,int index){auto uniform=[&](double lo,double hi){return art::uniform(volume_random,lo,hi);};const double angle=uniform(-pi,pi);const Point radial=from_angle(angle);const double speed=field.blast?uniform(14,55):uniform(12,45);Point velocity=radial*speed;if(field.gun)velocity=norm(field.direction*.35+radial)*(speed*.5)+Point{0,-6};Point point=radial*uniform(0,3);if(field.gun){const double forward=uniform(0,6),side=uniform(-1,1);point=field.direction*forward+Point{field.direction.y,-field.direction.x}*side;}const int radius=field.blast?volume_random.range(3,7):volume_random.range(1,3);Mote result;result.point=point;result.velocity=velocity;result.phase=angle;result.shade=index%3;result.pale=field.gun;for(int y=-radius;y<=radius;++y)for(int x=-radius;x<=radius;++x){const double distance=std::hypot(x,y)/radius;if(distance<uniform(.72,1.08)){result.mask.push_back({x,y});result.rim.push_back(x*x+y*y);}}result.heat=field.gun?uniform(.2,.55):uniform(.75,1);result.cool=field.gun?uniform(.06,.12):uniform(.012,.035);result.life=field.blast?volume_random.range(100,180):volume_random.range(20,50);return result;}
void LivingEffects::Impl::step_volume(){for(auto&f:fields){++f.age;f.dirty=true;for(auto&m:f.motes){m.heat=std::max(0.,m.heat-m.cool);const double phase=f.age*.09+m.phase;const Point drift{std::cos(phase)*9,std::sin(phase*.7)*4-9};m.velocity=m.velocity*.95+drift*.02;m.point=m.point+(m.velocity+drift)*.02;}std::erase_if(f.motes,[&](const Mote&m){return f.age>=m.life;});}std::erase_if(fields,[](const Blast&f){return f.age>=f.life;});}
void LivingEffects::Impl::raster(Blast&f,Canvas&canvas){std::fill(f.bytes.begin(),f.bytes.end(),0);auto write=[&](int x,int y,SDL_Color c){if(x<0||x>=f.width||y<0||y>=f.height)return;const int at=(y*f.width+x)*4;f.bytes[at]=c.r;f.bytes[at+1]=c.g;f.bytes[at+2]=c.b;f.bytes[at+3]=c.a;};for(bool hot:{false,true})for(const auto&m:f.motes){if((m.heat>.25)!=hot)continue;const Cell point{int(std::round(f.anchor.x+m.point.x/cell)),int(std::round(f.anchor.y+m.point.y/cell))};const double radius_sq=m.mask.size()/pi;if(radius_sq<=0)continue;if(hot){const double level=m.heat*5,spread=.6/radius_sq;for(std::size_t i=0;i<m.mask.size();++i){const Cell c=m.mask[i];const int x=point.x+c.x,y=point.y+c.y;if(x<0||y<0||x>=f.width||y>=f.height)continue;const int index=std::clamp(int(level*(1-m.rim[i]*spread)+bayer[(y&3)*4+(x&3)]-.25),0,5);auto tone=sdl(color(palette[index]));tone.a=235;write(x,y,tone);}continue;}const double fade=1-double(f.age)/m.life,shade=(m.pale?.5:.15)+m.shade*.035+.28*double(f.age)/m.life,radius=std::sqrt(radius_sq),limit=fade*1.7;const Color base{shade,shade+.012,shade+.028,1};const SDL_Color dark{Uint8(base.r*255),Uint8(base.g*255),Uint8(base.b*255),225},lit{Uint8(std::clamp(base.r+.1,0.,1.)*255),Uint8(std::clamp(base.g+.1,0.,1.)*255),Uint8(std::clamp(base.b+.11,0.,1.)*255),225};for(std::size_t i=0;i<m.mask.size();++i){const Cell c=m.mask[i];const int x=point.x+c.x,y=point.y+c.y;if(x<0||y<0||x>=f.width||y>=f.height)continue;if(limit-m.rim[i]/radius_sq<=bayer[(y&3)*4+(x&3)])continue;write(x,y,c.y< -radius*.3?lit:dark);}}
    if(f.age<9&&f.blast){const double radius=(f.age+1)*4.;for(int i=0;i<96;++i){const double angle=tau*i/96,ripple=1+std::sin(i*7.+f.age)*.09;const auto p=f.anchor+from_angle(angle)*(radius*ripple);write(int(std::round(p.x)),int(std::round(p.y)),sdl({1,.78,.35,.75*(1-f.age/9.)}));}}
    if(!f.texture){f.texture.reset(SDL_CreateTexture(canvas.renderer(),SDL_PIXELFORMAT_RGBA32,SDL_TEXTUREACCESS_STREAMING,f.width,f.height));if(!f.texture)throw std::runtime_error(SDL_GetError());SDL_SetTextureBlendMode(f.texture.get(),SDL_BLENDMODE_BLEND);SDL_SetTextureScaleMode(f.texture.get(),SDL_ScaleModeNearest);}render_check(SDL_UpdateTexture(f.texture.get(),nullptr,f.bytes.data(),f.width*4),"Blast volume update");f.dirty=false;
}
void LivingEffects::Impl::draw_volume(Canvas&canvas,Point offset){const auto view=projection(canvas);const float scale=view.scale,left=view.x,top=view.y;for(auto&f:fields){if(f.dirty)raster(f,canvas);const Point extent{f.width*cell*f.scale,f.height*cell*f.scale};const auto origin=snap(f.point+offset-f.anchor*(cell*f.scale));const SDL_FRect dest{left+float(origin.x)*scale,top+float(origin.y)*scale,float(extent.x)*scale,float(extent.y)*scale};render_check(SDL_RenderCopyF(canvas.renderer(),f.texture.get(),nullptr,&dest),"Blast volume draw");}}
}
